    SELECT pl.*,
       p1.CreationDate AS OriginPostCreate,
       p2.CreationDate AS RelatedPostCreate,
       CASE WHEN pl.LinkTypeId = 3 THEN 'Duplicate' ELSE 'Linked' END as RelationType
    FROM PostLinks pl
    JOIN Posts p1 ON p1.Id = pl.PostId
    JOIN Posts p2 ON p2.Id = pl.RelatedPostId
    WHERE pl.CreationDate<(current_timestamp),
